/* Short lessons in other school subjects (math, Hebrew, science, geography,
   history) — the same format and style as english-lessons.js: one idea per
   slide, very simple Hebrew. ready-lessons.js turns each entry into a full
   lesson (shortLesson): it adds the quiz, the class discussion, the games and
   the end slides.

   Lesson: { id, subject, topic, grades?, name, part?, summary, vocab, slides, quiz, discuss }
   - subject: "math" | "hebrew" | "science" | "geography" | "history" (the
     lessons-library filter).
   - topic: the library's topic filter id; lessons of one topic share a name
     and are numbered in the order they appear here ("שברים 1 – מה זה שבר").
   - grades: grade groups ("ag" / "dv" / "zh"); all three when left out.
   - vocab: [[term, meaning], ...] — the words the games use.
   - slides: { title, lines?, fig?, table?, tableHead?, examples?, flow?, compare?,
               math?, steps?, check?, grid?, verdicts?, proof?, points?, chips?, result? }
       lines: short Hebrew lines. fig: a drawing from lesson-figures.js
       ({ kind, ... }). table: [[from, to], ...] rows with an arrow, under an
       optional tableHead. examples: [[text, note], ...] cards; flow: a down
       arrow between them. compare: [wrong, right].
       math: ["...", [math, note], ...] — big math cards, optional note.
       steps: [[row, action?], ...] — solving steps lined up on "="; action is
         what both sides get ("·3" shows as "/ ·3"). The last row is the answer.
       check: the check of the answer, in math. grid: { head, rows } — a data
       table. verdicts: [[math, ok, note], ...]. proof: [[claim, reason], ...]
       under טענה / נימוק. points: numbered steps. chips: short items.
       result: the answer line.
   - quiz: [[q, exercise, options, answer, why], ...]; exercise is math shown
     big under the question, usually "". The quiz moves the right answer to a
     different place in each question, so it can be written anywhere.
   - discuss: the class-discussion questions.
   "$...$" in a Hebrew line is a math bit (read left to right). In math, {1|2}
   is a stacked fraction, √{25} a root, "-" a real minus and ** the key part;
   {1|2} works in Hebrew lines too.
   No girls' names, pictures or sentences about girls; boys' names only. */
